async function campaignsStep4(){
 $('#view').innerHTML=page('Daily products & PDFs.','Prepare a catalogue, choose a connection and schedule updates for subscribed customers.','<button class="btn" id="new-daily-update">+ Create update</button>')+'<div class="panel" id="campaign-list">Loading campaigns…</div>';
 $('#new-daily-update').onclick=createDailyUpdate;
 try{const state=await api('/campaigns');if(view!=='campaigns')return;store.campaigns=state.campaigns;
 $('#campaign-list').innerHTML=`<div class="panel-head"><h3>Your campaigns</h3><button class="btn secondary small" id="refresh-campaigns">Refresh</button></div><div class="note ${state.workerEnabled?'':'warning'}">${state.workerEnabled?'Sending worker is enabled. Only campaigns you explicitly schedule will send.':'Sending worker is OFF. Drafts and PDF preparation work. Set CAMPAIGN_WORKER_ENABLED=true in .env and restart before scheduling.'}</div><p>${store.customers.filter(c=>c.marketingConsent).length} subscribed customer(s). Each run rechecks consent and deduplicates phone numbers.</p>${table(['UPDATE','CONNECTION','SCHEDULE','STATUS',''],state.campaigns.map(c=>row([`<b>${esc(c.title)}</b><small>${c.autoPdf?'Fresh PDF generated each run':esc(c.fileName||'Uploaded PDF')}</small>`,c.mode==='official'?'Official template':'Linked device',c.nextAt?date(c.nextAt):c.recurrence==='daily'?esc(c.dailyTime+' · '+c.timezone):c.planned?date(c.planned):'Not set',pill(c.status),`<button class="btn secondary small" data-campaign-open="${c.id}">Manage</button>`])))}`;
 $('#refresh-campaigns').onclick=campaignsStep4;
 $$('[data-campaign-open]').forEach(b=>b.onclick=()=>manageCampaign(b.dataset.campaignOpen));
 }catch(e){if($('#campaign-list'))$('#campaign-list').textContent=e.message}
}
function createDailyUpdate(){modal(`<h2>Create a daily product update</h2><form id="edit-form">${input('title','Catalogue title','Daily fresh products','text','required maxlength="120"')}<div class="two-fields">${select('mode','WhatsApp connection',['official','web'],'official')}${select('recurrence','Repeat',['once','daily'],'once')}</div><label>Message / caption (linked device only)<textarea name="text" maxlength="3500" placeholder="Fresh products are ready. Reply with the items you need."></textarea></label><label class="check"><input type="checkbox" name="autoPdf" checked>Generate PDF from current in-stock products at each run</label><label>Or upload your own PDF (up to 8 MB)<input name="pdf" type="file" accept="application/pdf"></label><p class="hint">An uploaded PDF stays the same across daily runs. Prices shown in any PDF still require store confirmation.</p><div class="two-fields">${input('planned','One-time date / time','','datetime-local')}${input('dailyTime','Daily sending time','09:00','time')}</div>${input('timezone','Daily timezone','Asia/Kolkata','text','required')}<p class="hint">One-time schedules use this device's timezone. Daily schedules use the timezone above.</p><div id="official-template-fields"><h3 style="margin-top:22px">Official template settings</h3>${input('templateName','Approved MARKETING template with DOCUMENT header','','text','placeholder="daily_products"')}${input('language','Exact template language code','en','text')}<label>Numbered body parameters (JSON array)<textarea name="bodyParams" placeholder='["{{customer_name}}", "{{store_name}}"]'>[]</textarea></label><p class="hint">Use the exact parameter order approved in your template. {{customer_name}} and {{store_name}} are substituted per recipient. Include opt-out wording in your approved template.</p></div><div class="note warning" id="web-warning" hidden>Linked-device sending is unofficial. This application sends only to customers with recorded promotional consent. Keep the server and linked session running.</div>${formEnd('Save draft')}`);
 const toggle=()=>{$('#official-template-fields').hidden=$('[name=mode]').value==='web';$('#web-warning').hidden=$('[name=mode]').value!=='web'};$('[name=mode]').onchange=toggle;toggle();
 bindForm(async(b,form)=>{let f=null;const pdf=$('[name=pdf]',form).files[0];if(b.autoPdf!=='on'){if(!pdf)throw Error('Choose a PDF or enable automatic generation');if(pdf.size>8*1024*1024)throw Error('Maximum PDF size is 8 MB');const base64=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(pdf)});f=await api('/files','POST',{name:pdf.name,base64})}let params;try{params=JSON.parse(b.bodyParams||'[]')}catch{throw Error('Template parameters must be a valid JSON array')}await api('/campaigns','POST',{...b,autoPdf:b.autoPdf==='on',fileId:f?.id,fileName:f?.name,bodyParams:params,planned:b.planned?new Date(b.planned).toISOString():null});await campaignsStep4();toast('Draft saved. Review it before scheduling.')})
}
function manageCampaign(id){const c=store.campaigns.find(x=>x.id===id);if(!c)return;
 modal(`<h2>${esc(c.title)}</h2><div class="note">${pill(c.status)} · ${c.mode==='official'?'Official WhatsApp template':'Linked device'}<br>${c.recurrence==='daily'?'Daily at '+esc(c.dailyTime+' '+c.timezone):'One-time: '+(c.planned?date(c.planned):'Choose a date in a new draft')}</div><div class="preview-text">${esc(c.mode==='official'?'Template: '+c.templateName+' ('+c.language+')\nParameters: '+JSON.stringify(c.bodyParams):c.text)}</div><p>${c.autoPdf?'A new PDF will use the available products and prices at run time.':'The saved PDF will be reused.'}</p><div class="actions" style="flex-wrap:wrap"><button class="btn secondary" id="preview-catalogue">Preview PDF</button><button class="btn secondary" id="campaign-logs">Delivery logs</button>${['Scheduled','Sending'].includes(c.status)?'<button class="btn danger" id="pause-campaign">Pause</button>':'<button class="btn" id="schedule-campaign">Schedule sending</button>'}</div><p class="hint">Accepted means the provider accepted the message. It does not prove customer delivery or reading. Unknown sends are not automatically retried.</p>`);
 $('#preview-catalogue').onclick=async e=>{e.target.disabled=true;try{let fid=c.fileId;if(c.autoPdf){const f=await api('/campaigns/catalogue','POST',{title:c.title});fid=f.id}const a=document.createElement('a');a.href='/api/files/'+encodeURIComponent(fid);a.target='_blank';a.rel='noopener';a.textContent='Open generated PDF';a.className='btn secondary';e.target.replaceWith(a);toast('PDF ready. Click Open generated PDF.')}catch(err){toast(err.message);e.target.disabled=false}};
 $('#campaign-logs').onclick=async()=>{try{const logs=await api('/campaigns/'+id+'/logs');modal(`<h2>Campaign delivery logs</h2><p>${esc(c.title)} · Latest 1,000 log rows</p>${table(['RUN','PHONE','RESULT','PROVIDER ID','DETAIL'],logs.map(l=>row([date(l.started_at),esc(l.phone||'—'),pill(l.delivery_status||l.status),esc(l.provider_id||'—'),esc(l.error||'—')])))}`)}catch(e){toast(e.message)}};
 $('#schedule-campaign')?.addEventListener('click',async e=>{const audience=store.customers.filter(x=>x.marketingConsent).length;if(!confirm(`Schedule ${c.recurrence==='daily'?'recurring daily':'one-time'} WhatsApp PDF updates for subscribed customers (currently ${audience})? This sends real messages when due.`))return;e.target.disabled=true;try{await api('/campaigns/'+id+'/schedule','POST',{});close();await campaignsStep4();toast('Campaign scheduled')}catch(err){toast(err.message);e.target.disabled=false}});
 $('#pause-campaign')?.addEventListener('click',async()=>{try{await api('/campaigns/'+id+'/pause','POST',{});close();await campaignsStep4();toast('Paused. A message already submitted to WhatsApp cannot be recalled.')}catch(e){toast(e.message)}});
}
campaigns=campaignsStep4;
automations=async function(){
 $('#view').innerHTML=page('Your automation plan.','Daily catalogue sending is ready to configure. Other workflows remain separate integrations.')+`<div class="panel"><div class="card-row"><span class="row-icon">▤</span><div><b>Daily PDF and product updates</b><small>One-time / daily schedules, subscription checks and delivery logs</small></div><button class="btn" id="open-campaigns">Configure</button></div>${['Welcome replies','Automatic order confirmations','Payment gateway reconciliation','Automatic delivery updates'].map(t=>`<div class="card-row"><div><b>${t}</b></div><span class="pill neutral" style="margin-left:auto">Not enabled</span></div>`).join('')}<div class="note">Scheduled catalogue sending needs a running backend, an enabled campaign worker, a connected WhatsApp account, and approved templates for official campaigns.</div></div>`;$('#open-campaigns').onclick=()=>navigate('campaigns');
};
